correctedCode:
public class SignChecker {
    static String describe(int n) {
        if (n > 0) {
            return "positive";
        } else if (n < 0) {
            return "negative";
        } else {
            return "zero";
        }
    }

    public static void main(String[] args) {
        System.out.println(describe(5));
    }
}
